// Generated by aistatus — do not edit by hand.
// Re-run: aistatus install-hooks --agent opencode
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const PY = __PY__;
const AI_STATUS_HOME = __AI_STATUS_HOME__;
const ALLOWED = __EVENTS__;
const LOG = path.join(AI_STATUS_HOME, "opencode.log");
const BLOCKED = path.join(AI_STATUS_HOME, "blocked.json");
let blockedCache = { at: 0, set: new Set() };

// Muted sessions (written by the menu bar app) are dropped before spawning a hook.
function isBlocked(sid) {
  const now = Date.now();
  if (now - blockedCache.at > 2000) {
    let set = new Set();
    try {
      const obj = JSON.parse(fs.readFileSync(BLOCKED, "utf8"));
      set = new Set(Object.keys(obj || {}));
    } catch (e) {}
    blockedCache = { at: now, set };
  }
  return blockedCache.set.has(sid);
}

const lastTitle = new Map();
const lastDir = new Map();
const lastQuestion = new Map();   // part id -> last status we forwarded
const lastThinking = new Map();   // part id -> already reported thinking
const pendingQuestion = new Set(); // sessions currently blocked on a question
const pendingPermission = new Set(); // sessions waiting on a permission prompt
const inflight = new Map();        // sessionID -> running tool count
const heartbeats = new Map();      // sessionID -> interval id
const metaFetched = new Set();     // sessionID -> already fetched name/dir via ctx.session.get
const busyAt = new Map();          // sessionID -> last "busy" forward (dedupe hook vs event)
const workAt = new Map();          // sessionID -> last "working" forward

// opencode v2 emits both a tool hook (execute.before/after) and a public
// `session.tool.called/success` event for the same call. Only the first source
// within a short window is forwarded, so the state doesn't double-fire.
const BUSY_DEDUPE_MS = 800;
function dedupeGate(map, sid) {
  const now = Date.now();
  const t = map.get(sid) ?? 0;
  if (now - t < BUSY_DEDUPE_MS) return true;
  map.set(sid, now);
  return false;
}

// opencode v2 makes the title hard to observe: only `session.created` and
// `session.renamed` carry it, so a session that already existed when the plugin
// loaded never gets a name (the light falls back to the agent label). Fetch it
// once per session straight from the session object, where it lives.
async function ensureMeta(ctx, sessionID, title, dir) {
  if (!sessionID || title) return;                      // event already had a title
  if (lastTitle.has(sessionID) || metaFetched.has(sessionID)) return;
  metaFetched.add(sessionID);
  try {
    const res = await ctx.session.get({ sessionID });
    const info = res?.data ?? res ?? {};
    const t = info.title ?? null;
    const d = info.location?.directory ?? info.directory ?? dir ?? null;
    if (!t && !d) return;
    if (t) lastTitle.set(sessionID, t);
    log(`meta ${sessionID} title=${JSON.stringify(t)} dir=${JSON.stringify(d)}`);
    forward("session.updated", { sessionID, session_name: t, session_dir: d });
  } catch (e) {
    log(`session.get failed ${sessionID}: ${e?.message ?? e}`);
  }
}

const HEARTBEAT_MS = 180000;       // refresh while a tool runs (3 min)

function startHeartbeat(sid) {
  if (heartbeats.has(sid)) return;
  const id = setInterval(() => {
    if (!inflight.get(sid)) {
      clearInterval(id);
      heartbeats.delete(sid);
      return;
    }
    forward("heartbeat", { sessionID: sid });
  }, HEARTBEAT_MS);
  heartbeats.set(sid, id);
}

function stopHeartbeat(sid) {
  if (inflight.get(sid)) return;
  const id = heartbeats.get(sid);
  if (id) {
    clearInterval(id);
    heartbeats.delete(sid);
  }
}

const QUESTION_TOOL = "question";

// Host terminal/desktop detection (drives which app the menu bar jumps to).
const TERM_HOSTS = {
  "iTerm.app": "com.googlecode.iterm2",
  "vscode": "com.microsoft.VSCode",
  "Apple_Terminal": "com.apple.Terminal",
  "WarpTerminal": "dev.warp.Warp-Stable",
  "WezTerm": "com.github.wez.wezterm",
  "Hyper": "co.zeit.hyper",
  "Tabby": "org.tabby",
};
function detectHost() {
  try { if (process.versions && process.versions.electron) return "ai.opencode.desktop"; } catch (e) {}
  const tp = process.env.TERM_PROGRAM || "";
  if (TERM_HOSTS[tp]) return TERM_HOSTS[tp];
  if (tp) return null;                       // unknown terminal → let the app decide
  return "ai.opencode.desktop";              // no terminal info → desktop app
}
const HOST = detectHost();
const HOST_REF = process.env.ITERM_SESSION_ID || process.env.TERM_SESSION_ID || null;

function log(line) {
  try {
    fs.mkdirSync(AI_STATUS_HOME, { recursive: true });
    fs.appendFileSync(LOG, new Date().toISOString() + "  " + line + "\n");
  } catch (e) {}
}

function safeStringify(value) {
  try {
    return JSON.stringify(value);
  } catch (e) {
    try {
      const seen = new Set();
      return JSON.stringify(value, (k, v) => {
        if (typeof v === "object" && v !== null) {
          if (seen.has(v)) return undefined;
          seen.add(v);
        }
        return v;
      });
    } catch (e2) {
      log(`stringify failed: ${e2 && e2.message}`);
      return "{}";
    }
  }
}

// Concurrent forwards with a timeout. Ordering is guaranteed by the store's
// monotonic `seq` (stale writes are ignored), so we never serialize — a single
// slow/hung child must not stall every later event.
const HOOK_TIMEOUT_MS = 8000;

function forward(eventType, properties) {
  const sid = properties.sessionID ?? properties.sessionId ?? null;
  if (sid && isBlocked(sid)) return;                 // muted → never monitored
  const payload = safeStringify({
    session_id: sid,
    session_name: properties.session_name ?? null,
    session_dir: properties.session_dir ?? properties.info?.directory ?? properties.directory ?? null,
    session_host: HOST,
    session_ref: HOST_REF,
    message: properties.message ?? null,
    seq: Date.now(),
    event: eventType,
    properties,
  });
  let child;
  try {
    child = spawn(PY, ["-m", "aistatus", "hook", "--agent", "opencode", "--default-state", "", "--verbose"], {
      env: { ...process.env, AISTATUS_HOME: AI_STATUS_HOME },
      stdio: ["pipe", "ignore", "pipe"],
    });
  } catch (e) {
    log(`hook spawn threw ${eventType}: ${e}`);
    return;
  }
  let err = "";
  let done = false;
  const finish = (reason) => {
    if (done) return;
    done = true;
    clearTimeout(timer);
    const msg = err.trim();
    if (reason || msg || eventType.startsWith("question")) {
      log(`hook ${reason ?? "ok"} ${eventType}${msg ? " :: " + msg.split("\n").slice(-2).join(" | ") : ""}`);
    }
  };
  const timer = setTimeout(() => {
    try { child.kill("SIGKILL"); } catch (e) {}
    finish("timeout");
  }, HOOK_TIMEOUT_MS);
  child.stderr.on("data", (d) => { err += d.toString(); });
  child.on("error", (e) => { err += String(e); finish("spawn-error"); });
  child.on("exit", (code) => finish(code ? "exit=" + code : null));
  try {
    child.stdin.end(payload);
  } catch (e) {
    err += String(e);
    finish("stdin-error");
  }
}

// A permission / question prompt is usually announced milliseconds *before* the
// `tool.execute.before` "busy" that triggered it. Re-sending the blocked event a
// moment later gives it a higher `seq`, so "blocked" always wins the store's
// ordering even when the two hook processes race.
const REINFORCE_MS = 400;
const reinforceTimers = new Map();

function cancelReinforce(sid) {
  const t = reinforceTimers.get(sid);
  if (t) { clearTimeout(t); reinforceTimers.delete(sid); }
}

function reinforce(eventType, properties, sid) {
  cancelReinforce(sid);
  const t = setTimeout(() => {
    reinforceTimers.delete(sid);
    if (!pendingQuestion.has(sid) && !pendingPermission.has(sid)) return;   // already answered
    log(`reinforce ${eventType} sid=${sid}`);
    forward(eventType, properties);
  }, REINFORCE_MS);
  reinforceTimers.set(sid, t);
}

function pick(value, ...keys) {
  for (const k of keys) if (value?.[k] != null) return value[k];
  return undefined;
}

// ---------------------------------------------------------------------------
// Hook bodies (original V1 logic, unchanged). Driven by the V2 entrypoint at
// the bottom of this file.
// ---------------------------------------------------------------------------
async function onToolBefore(input) {
      const sid = input?.sessionID;
      if (!sid) return;
      if (dedupeGate(busyAt, sid)) return;   // hook + event may both fire; keep one
      inflight.set(sid, (inflight.get(sid) ?? 0) + 1);
      startHeartbeat(sid);
      // The question tool means "waiting for the user" → blocked, not busy.
      if (input?.tool === QUESTION_TOOL) {
        pendingQuestion.add(sid);
        return;
      }
      if (pendingQuestion.has(sid) || pendingPermission.has(sid)) return;
      log(`tool.before sid=${sid} tool=${input?.tool}`);
  forward("tool.before", { sessionID: sid, tool: input?.tool });
}

async function onToolAfter(input) {
      const sid = input?.sessionID;
      if (!sid) return;
      inflight.set(sid, Math.max(0, (inflight.get(sid) ?? 1) - 1));
      stopHeartbeat(sid);
      // question.replied already returns to working.
      if (input?.tool === QUESTION_TOOL) {
        pendingQuestion.delete(sid);
        return;
      }
      if (pendingQuestion.has(sid) || pendingPermission.has(sid)) return;
      if (dedupeGate(workAt, sid)) return;   // hook + event may both fire; keep one
  forward("tool.after", { sessionID: sid, tool: input?.tool });
}

async function handleEvent(event) {
      const type = event?.type;
      if (!type || !ALLOWED.includes(type)) return;
      const props = event?.properties ?? event?.data ?? {};
      const info = props.info ?? {};
      const sessionID = pick(props, "sessionID", "sessionId")
        ?? pick(info, "id")
        ?? pick(event, "sessionID", "sessionId");
      if (!sessionID) return;
      const title = info.title ?? props.title;
      const dir = info.directory ?? props.directory;

      // A permission prompt keeps the session blocked; remember it.
      if (type === "permission.asked" || type === "permission.updated") {
        pendingPermission.add(sessionID);
        reinforce(type, { ...props, sessionID, session_name: title, session_dir: dir }, sessionID);
      } else if (type === "permission.replied") {
        pendingPermission.delete(sessionID);
        cancelReinforce(sessionID);
      }

      // Reasoning → thinking (once per session turn).
      if (type === "thinking") {
        if (!pendingQuestion.has(sessionID)) {
          log(`thinking sid=${sessionID}`);
          forward("thinking", { sessionID });
        }
        return;
      }

      // The agent is waiting on the user. In opencode v2 the `question` tool is
      // surfaced as a form; treat form.created/replied as question.asked/replied.
      if (type === "question.asked") {
        pendingQuestion.add(sessionID);
        const qid = props.part?.id ?? sessionID;
        if (lastQuestion.get(qid) !== "running") {
          lastQuestion.set(qid, "running");
          log(`question.asked sid=${sessionID} ${JSON.stringify(props.message ?? null)}`);
          const props2 = { sessionID, message: props.message ?? null, part: props.part };
          forward("question.asked", props2);
          reinforce("question.asked", props2, sessionID);
        }
        return;
      }
      if (type === "question.replied") {
        const qid = props.part?.id ?? sessionID;
        pendingQuestion.delete(sessionID);
        cancelReinforce(sessionID);
        if (lastQuestion.get(qid) !== "done") {
          lastQuestion.set(qid, "done");
          log(`question.replied sid=${sessionID}`);
          forward("question.replied", { sessionID });
        }
        return;
      }

      // While a question/permission is pending, ignore busy so it can't
      // overwrite blocked.
      if (type === "session.status") {
        const st = props.status?.type;
        if (st === "idle") {
          pendingQuestion.delete(sessionID);
          pendingPermission.delete(sessionID);
          cancelReinforce(sessionID);
        } else if (st === "busy" && (pendingQuestion.has(sessionID) || pendingPermission.has(sessionID))) {
          return;
        }
      }

      // session.updated fires often; only forward when title/directory changes.
      if (type === "session.updated") {
        const titleChanged = title && lastTitle.get(sessionID) !== title;
        const dirChanged = dir && lastDir.get(sessionID) !== dir;
        if (!titleChanged && !dirChanged) return;
      }
      if (title) lastTitle.set(sessionID, title);
      if (dir) lastDir.set(sessionID, dir);
      log(`${type} sid=${sessionID} title=${JSON.stringify(title ?? null)} dir=${JSON.stringify(dir ?? null)} status=${JSON.stringify(pick(props, "status"))}`);
      forward(type, { ...props, sessionID, session_name: title, session_dir: dir });
}

// ---------------------------------------------------------------------------
// V2 bridge: translate opencode v2 events (`event.data`) into the V1-shaped
// `{ type, properties }` objects the state machine above already understands.
// Semantic mapping to the store lives in the Python side (store.opencode_state).
// ---------------------------------------------------------------------------
function fromV2(ev) {
  const type = ev?.type;
  const d = ev?.data ?? ev?.properties ?? {};
  switch (type) {
    case "session.status":
      return { type: "session.status", properties: { sessionID: d.sessionID, status: d.status } };
    case "session.idle":
      return { type: "session.idle", properties: { sessionID: d.sessionID } };
    // opencode v2 no longer emits session.status/session.idle; a turn's
    // boundaries are signalled by session.execution.* (started = busy).
    case "session.execution.started":
      return { type: "session.status", properties: { sessionID: d.sessionID, status: { type: "busy" } } };
    case "session.execution.succeeded":
      return { type: "session.idle", properties: { sessionID: d.sessionID } };
    case "session.execution.failed":
      return { type: "session.error", properties: { sessionID: d.sessionID, error: d.error } };
    case "session.created":
      return { type: "session.created", properties: {
        sessionID: d.sessionID ?? ev?.durable?.aggregateID ?? null,
        info: { title: d.info?.title ?? d.title,
                directory: d.info?.directory ?? d.location?.directory },
      } };
    case "session.renamed":
      return { type: "session.updated", properties: { sessionID: d.sessionID,
        info: { title: d.info?.title ?? d.title,
                directory: d.info?.directory ?? d.directory } } };
    // The session object (title/directory) also arrives nested under `data.info`;
    // read it so a renamed or updated session always surfaces its name.
    case "session.updated":
      return { type: "session.updated", properties: { sessionID: d.sessionID,
        info: { title: d.info?.title ?? d.title,
                directory: d.info?.directory ?? d.directory } } };
    case "permission.asked":
      return { type: "permission.asked", properties: {
        sessionID: d.sessionID, id: d.id, action: d.action, resources: d.resources,
        metadata: d.metadata, source: d.source, message: d.message,
      } };
    case "permission.replied":
      return { type: "permission.replied", properties: { sessionID: d.sessionID, requestID: d.requestID, reply: d.reply } };
    case "session.reasoning.started":
      return { type: "thinking", properties: { sessionID: d.sessionID } };
    case "form.created": {
      const f = d.form ?? {};
      const questions = Array.isArray(f.fields)
        ? f.fields.map((field) => ({ question: field?.label ?? field?.placeholder ?? "" }))
        : [];
      return { type: "question.asked", properties: {
        sessionID: f.sessionID ?? f.sessionId ?? d.sessionID ?? null,
        message: questions[0]?.question ?? null,
        part: { id: f.id ?? d.id ?? null, type: "tool", tool: QUESTION_TOOL, state: { status: "running" } },
      } };
    }
    case "form.replied":
    case "form.cancelled":
      return { type: "question.replied", properties: { sessionID: d.sessionID } };
    default:
      return null;
  }
}

// V2 can invoke setup twice for one loaded instance (server boot + first app
// load), often concurrently. Claim a MODULE-scoped slot synchronously (no await
// before the claim) so one instance registers only once. Crucially this is NOT
// on globalThis: opencode hot-reloads a plugin when its file changes by
// re-importing the module, so a fresh evaluation must register again. A
// globalThis flag would make the reloaded instance skip registration while the
// old registrations are already disposed — silently killing the tool hooks.
let active = false;

export default {
  id: "aistatus",
  async setup(ctx) {
    if (active) {
      log("setup called again; already active, skipping duplicate");
      return () => {};
    }
    active = true;
    log(`plugin loaded host=${HOST} ref=${HOST_REF ?? "null"}`);
    // Tool hooks replace the V1 "tool.execute.before/after" hooks.
    try {
      await ctx.tool.hook("execute.before", async (event) => {
        await onToolBefore({ sessionID: event?.sessionID, tool: event?.tool });
      });
      await ctx.tool.hook("execute.after", async (event) => {
        await onToolAfter({ sessionID: event?.sessionID, tool: event?.tool });
      });
    } catch (e) {
      log(`hook registration failed: ${e?.message ?? e}`);
    }
    // Event subscription replaces the V1 `event` hook.
    const controller = new AbortController();
    void (async () => {
      try {
        for await (const ev of ctx.event.subscribe({ signal: controller.signal })) {
          const raw = ev?.type;
          const d = ev?.data ?? {};
          // Tool activity is visible as a public event too; forward it directly
          // (it is not part of the ALLOWED set handled below).
          if (raw === "session.tool.called") {
            await onToolBefore({ sessionID: d.sessionID, tool: d.tool ?? d.name });
            continue;
          }
          if (raw === "session.tool.success" || raw === "session.tool.failed") {
            await onToolAfter({ sessionID: d.sessionID, tool: d.tool ?? d.name });
            continue;
          }
          const mapped = fromV2(ev);
          if (!mapped) continue;
          // The envelope carries `location.directory` on every event, so the
          // directory is also available one level up from `data`.
          const envDir = ev?.location?.directory;
          if (envDir && !mapped.properties.session_dir) mapped.properties.session_dir = envDir;
          void ensureMeta(ctx, mapped.properties.sessionID,
                          mapped.properties.info?.title ?? mapped.properties.session_name, envDir);
          handleEvent(mapped);
        }
      } catch (e) {
        if (!controller.signal.aborted) log(`event stream error: ${e?.message ?? e}`);
      }
    })();
    return () => {
      active = false;
      try { controller.abort(); } catch (e) {}
      for (const id of heartbeats.values()) { try { clearInterval(id); } catch (e) {} }
      heartbeats.clear();
      for (const t of reinforceTimers.values()) { try { clearTimeout(t); } catch (e) {} }
      reinforceTimers.clear();
    };
  },
};
